import cmath
import itertools
import random


class Poly:
    def __init__(self, coeff: list):
        self.coeff = coeff
        self.coeff.reverse()
        self.coeff = list(itertools.dropwhile(lambda x: x == 0, self.coeff))
        self.coeff.reverse()

        if len(self.coeff) == 0:
            self.coeff = [0]

    def get_degree(self):
        return len(self.coeff) - 1

